const filters=document.querySelectorAll('[data-filter]');const projects=document.querySelectorAll('.project');const count=document.querySelector('.work-count');filters.forEach(button=>button.addEventListener('click',()=>{const type=button.dataset.filter;filters.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});let visible=0;projects.forEach(project=>{project.hidden=type!=='all'&&project.dataset.type!==type;if(!project.hidden)visible++});count.textContent=String(visible).padStart(2,'0')+' PROJECT'+(visible===1?'':'S')}));const menu=document.querySelector('.menu-toggle');const mobile=document.querySelector('.mobile-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));mobile.classList.toggle('open',open)});mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobile.classList.remove('open');menu.setAttribute('aria-expanded','false')}));const data={threshold:{title:'Threshold Museum',meta:'CULTURAL / JOSHUA TREE, USA / 2025',image:'assets/hero.jpg',alt:'A monumental concrete museum in a desert basin',text:'A sequence of shadowed galleries opens toward a vast and unchanging horizon. Heavy planes frame the desert as a work in its own right; the building becomes a threshold between contemplation and landscape.'},shore:{title:'House at the Edge',meta:'RESIDENTIAL / ATLANTIC COAST / 2024',image:'assets/house.jpg',alt:'A concrete coastal house over the ocean',text:'Balanced between land and sea, a single concrete volume offers shelter from the elements. Deep openings frame the water and bring the changing weather into everyday life.'},library:{title:'The Silent Library',meta:'CULTURAL / KYOTO, JAPAN / 2023',image:'assets/interior.jpg',alt:'A concrete library interior with a shaft of daylight',text:'A sanctuary for thought, composed of quiet rooms and a single line of light. The rhythm of the sun becomes the building’s clock, marking moments of pause throughout the day.'}};const dialog=document.querySelector('#projectDialog');let previousFocus;document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const item=data[button.dataset.project];previousFocus=button;dialog.querySelector('img').src=item.image;dialog.querySelector('img').alt=item.alt;dialog.querySelector('#dialogTitle').textContent=item.title.toUpperCase();dialog.querySelector('.dialog-meta').textContent=item.meta;dialog.querySelector('.dialog-text').textContent=item.text;dialog.showModal();dialog.querySelector('.dialog-close').focus()}));dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>previousFocus?.focus());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
